// Block (composition) — one offer in a comparison list: who sells it, what it gives, what it costs.
// Card owns the surface, Rating the stars, Badge the tags, ToggleButton the favourite and
// Collapsible the benefit row; this Block arranges them and inks its own text (block-contract.md
// § 5). The price is a discounted price the product flags, so it takes the emphasis ink.
import type { ReactNode, Ref } from "react";
import { Heading } from "react-aria-components";
import { Heart } from "../components/icons";
import { Badge } from "../components/Badge";
import { Card, CardContent } from "../components/Card";
import { Collapsible } from "../components/Collapsible";
import { Link } from "../components/Link";
import { Rating } from "../components/Rating";
import { Separator } from "../components/Separator";
import { ToggleButton } from "../components/ToggleButtonGroup";
import { Indent } from "../layouts/Indent";
import { Stack } from "../layouts/Stack";
import "./PlanCard.css";

export interface PlanCardProps {
  /**
   * The provider's mark and its name for assistive tech. A string is a wordmark: text on the card's
   * surface, so the card sets it one `text-inset.inline` in (component-contract.md §6 rule 8). A node
   * is a logo box and stays on the box line.
   */
  provider: { mark: ReactNode; name: string };
  /** Average review score out of 5, shown as one star and the number. */
  rating?: number;
  /** The plan's own name, above the headline spec. */
  planName?: string;
  /** The headline spec, e.g. "120GB a month + 5Mbps". It is the card's title. */
  title: string;
  /**
   * Heading level of the title, so the card sits at the right depth in the page outline: `2` for a
   * list placed directly under the page's h1. Card's `headingLevel`, and the same default.
   *
   * @default 3
   */
  headingLevel?: 1 | 2 | 3 | 4 | 5 | 6;
  /**
   * A `ContextualHelp` after the title, for what the headline spec means (the speed once the
   * allowance runs out). A note the reader opens, so the card stays one line per fact.
   */
  titleHelp?: ReactNode;
  /** Where the title links to: the plan's detail page. */
  href?: string;
  /** Short specs on one line, e.g. ["Unlimited calls", "Unlimited texts", "5G"]. */
  specs?: string[];
  /** Tags such as "Cashback included". */
  badges?: string[];
  /** The price the customer pays, already formatted. */
  price: string;
  /** A `ContextualHelp` after the price, for how it is reached (a cashback it already counts). */
  priceHelp?: ReactNode;
  /** One line under the price, e.g. "From month 7: 41,000 won". */
  priceNote?: string;
  /** A social-proof caption, e.g. "271,711 people chose this". */
  popularity?: string;
  /** Whether the plan is in the customer's favourites. Controlled when `onFavoriteChange` is
   *  passed; otherwise the starting value of a toggle that keeps its own state. */
  isFavorite?: boolean;
  /** Called when the favourite toggle changes. */
  onFavoriteChange?: (isFavorite: boolean) => void;
  /** Read before the plan's title as the favourite toggle's name, e.g. "찜" → "찜 <title>".
   *
   * @default "Save"
   */
  favoriteLabel?: string;
  /** An expandable row of extra benefits: its summary line, and what it reveals. */
  benefit?: { summary: ReactNode; content: ReactNode };
  /** A mark at the header's end, e.g. a Badge naming how the plan is opened. */
  tag?: ReactNode;
  /**
   * For a list on a phone, where the reference product lets each plan run edge to edge: no card box,
   * the content on the page's own line, parted from its neighbours by whatever the list puts between
   * them (a Separator band).
   *
   * @default false
   */
  isFlush?: boolean;
  /** A label set above the card for the one highlighted offer in a list. */
  featuredLabel?: string;
  className?: string;
  ref?: Ref<HTMLDivElement>;
}

export function PlanCard({
  provider,
  rating,
  planName,
  title,
  headingLevel = 3,
  titleHelp,
  href,
  specs,
  badges,
  price,
  priceHelp,
  priceNote,
  popularity,
  isFavorite,
  onFavoriteChange,
  favoriteLabel = "Save",
  benefit,
  tag,
  isFlush = false,
  featuredLabel,
  className,
  ref,
}: PlanCardProps) {
  const cls = className ? `sd-plancard ${className}` : "sd-plancard";
  const body = (
        <Stack gap="medium">
          {featuredLabel && (
            <Badge variant="tonal" className="sd-plancard__featured">{featuredLabel}</Badge>
          )}
          {/* `between` sets the distance; the gap is only the floor a long provider name meets the tag at. */}
          <Stack direction="row" align="center" justify="between" gap="large">
            <Stack direction="row" align="center" gap="small" className="sd-plancard__provider">
              {typeof provider.mark === "string" ? (
                <>
                  <span className="sd-plancard__mark sd-type-label-medium" aria-label={provider.name} role="img">
                    {provider.mark}
                  </span>
                </>
              ) : (
                /* A drawn mark carries no type role, so Indent gives it the text inset a wordmark's role gives
                   it: both stand on the text start line (rule 8). */
                <Indent className="sd-plancard__mark" aria-label={provider.name} role="img">{provider.mark}</Indent>
              )}
              {rating !== undefined && (
                /* One star and the score, the compact readout a list card carries. */
                <Rating variant="single" size="small" value={rating} isReadOnly aria-label={`Rated ${rating.toFixed(1)} out of 5`} />
              )}
            </Stack>
            {tag}
          </Stack>
          {/* Everything here is on the Card's surface: text and the provider mark take the inset
              (rule 8), the badges stay on the box line. */}
          <>
            <Stack gap="2x-small">
              {/* The plan's own name shares its line with the favourite toggle, so the title and the
                  specs below run the full width (the reference card's arrangement). */}
              <Stack direction="row" align="center" justify="between" gap="small">
                {planName ? <p className="sd-plancard__plan sd-type-caption-medium">{planName}</p> : <span />}
                {/* usage: chrome — the card's one reaction control, at the end of the plan's own lines.
                    `quiet`: no plate, the heart itself fills in the brand ink when saved. */}
                <ToggleButton
                  variant="quiet"
                  size="small"
                  isIconOnly
                  aria-label={`${favoriteLabel} ${title}`}
                  {...(onFavoriteChange
                    ? { isSelected: isFavorite, onChange: onFavoriteChange }
                    : { defaultSelected: isFavorite })}
                >
                  <Heart aria-hidden size="1em" />
                </ToggleButton>
              </Stack>
              {/* The help sits beside the heading, never inside it, so the heading's name stays the title. */}
              <Stack direction="row" align="center" gap="2x-small">
                {/* React Aria's Heading, as CardTitle uses: safe inside a Dialog's heading context. */}
                <Heading level={headingLevel} className="sd-plancard__title sd-type-title-medium">
                  {href ? <Link href={href} variant="quiet">{title}</Link> : title}
                </Heading>
                {titleHelp}
              </Stack>
              {/* body-small: CONTRASTIVE, the specs read one rung under the title they spell out */}
              {specs && specs.length > 0 && (
                <ul className="sd-plancard__specs sd-type-body-small">
                  {specs.map((spec) => (
                    <li key={spec} className="sd-plancard__spec sd-type-body-small">
                      {/* A thin rule before every spec, centred in the gap; the list clips the one that
                          would lead a line, so a wrapped line neither starts nor ends on a rule. */}
                      <Separator isDecorative orientation="vertical" className="sd-plancard__spec-rule" />
                      {spec}
                    </li>
                  ))}
                </ul>
              )}
            </Stack>
          </>
          {badges && badges.length > 0 && (
            <Stack direction="row" gap="x-small" wrap align="start">
              {badges.map((badge) => (
                <Badge key={badge} variant="tonal">{badge}</Badge>
              ))}
            </Stack>
          )}
          <>
            <Stack gap="2x-small">
              {/* title-medium, the title's own rung: the price reads level with the plan it prices, as the
                  reference card sets them. */}
              <Stack direction="row" align="center" gap="2x-small">
                <p className="sd-plancard__price sd-type-title-medium">{price}</p>
                {priceHelp}
              </Stack>
              {(priceNote || popularity) && (
                <Stack direction="row" justify="between" gap="small" wrap>
                  {priceNote && <p className="sd-plancard__note sd-type-caption-medium">{priceNote}</p>}
                  {/* caption-small: social proof, one rung below the price note it sits beside */}
                  {popularity && <p className="sd-plancard__note sd-type-caption-small">{popularity}</p>}
                </Stack>
              )}
            </Stack>
          </>
          {benefit && (
            <Stack gap="small">
              <Separator isDecorative />
              {/* A summary row closing the card: the summary at the start, the chevron at the end. Its
                  body-small is CONTRASTIVE, a closing aside one rung under the card's body lines. */}
              {/* The row and what it reveals are text on the card's surface, so the whole disclosure
                  takes the inset (rule 8); its hover fill bleeds back out to the box line. */}
              <>
                <Collapsible chevronPlacement="end" title={<span className="sd-plancard__benefit sd-type-body-small">{benefit.summary}</span>}>
                  {benefit.content}
                </Collapsible>
              </>
            </Stack>
          )}
        </Stack>
  );
  return isFlush ? (
    <article ref={ref} data-flush="" className={cls}>
      {body}
    </article>
  ) : (
    <Card ref={ref} className={cls}>
      <CardContent>{body}</CardContent>
    </Card>
  );
}

/* PlanCard.css — .sd-plancard (Block)
   Arrangement, plus the ink of this Block's own text (block-contract.md § 5). Card, Badge, Rating,
   ToggleButton and Collapsible own every other look. */
.sd-plancard__plan,
.sd-plancard__title,
.sd-plancard__price,
.sd-plancard__note,
.sd-plancard__specs {
  margin: 0;
}

/* Flush: no card box, so the Block insets its own block axis, on the rung a medium surface pads at;
   the inline edge is the page's. */
.sd-plancard[data-flush] {
  padding-block: var(--sd-space-medium);
}

/* A chip in a column hugs its label rather than spanning the card (block-contract.md § 4). */
.sd-plancard__featured {
  align-self: start;
}

.sd-plancard__mark {
  display: inline-flex;
  align-items: center;
  block-size: var(--sd-icon-large);
}

.sd-plancard__plan,
.sd-plancard__note,
.sd-plancard__benefit {
  color: var(--sd-color-text-muted);
}

/* The benefit summary is a row: it may lead with logos (an AvatarGroup), and a block inside an inline
   span would open an empty line box above and below it, adding a text line's height to the row on
   each side. */
.sd-plancard__benefit {
  display: flex;
  align-items: center;
  gap: var(--sd-space-x-small);
}

/* Specs read as one wrapping line of muted text with a Separator in each gap. Each spec carries
   its rule just before it, out of flow and centred in the gap, and the list clips at its own edge,
   so the rule that would lead a wrapped line falls outside and none trails a line. The list carries no padding, so the clip edge IS the start line. */
.sd-plancard__specs {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sd-space-2x-small) var(--sd-space-medium);
  padding: 0;
  overflow: hidden;
  list-style: none;
  color: var(--sd-color-text-muted);
}

.sd-plancard__price {
  color: var(--sd-color-text-emphasis);
}

.sd-plancard__spec {
  position: relative;
}

/* Shorter than the line it parts, so it reads as punctuation; half a gap before its spec. Its
   min-height is reset, since a vertical Separator otherwise floors at its own minimum. */
.sd-plancard__spec-rule {
  position: absolute;
  inset-block-start: 50%;
  inset-inline-start: calc(var(--sd-space-medium) / -2);
  block-size: 0.75em;
  min-block-size: 0;
  translate: -50% -50%;
}
